<?php
namespace App\Http\Controllers;
use App\Models\Volunteer; use App\Models\VolunteerHour; use Illuminate\Http\Request;
class VolunteerPortalController extends Controller { public function index(){ $volunteer=Volunteer::where('user_id',auth()->id())->firstOrFail(); $hours=VolunteerHour::where('volunteer_id',$volunteer->id)->latest('started_at')->paginate(15); $total=VolunteerHour::where('volunteer_id',$volunteer->id)->sum('hours'); return view('volunteer.dashboard',compact('volunteer','hours','total')); } public function checkIn(){ $v=Volunteer::where('user_id',auth()->id())->where('status','approved')->firstOrFail(); VolunteerHour::create(['volunteer_id'=>$v->id,'activity'=>'Volunteer session','started_at'=>now()]); return back()->with('success','Checked in successfully.'); } public function checkOut(VolunteerHour $hour){abort_unless($hour->volunteer->user_id===auth()->id() && !$hour->ended_at,403);$hour->ended_at=now();$hour->hours=round($hour->started_at->diffInMinutes($hour->ended_at)/60,2);$hour->save();return back()->with('success','Checked out successfully.');} }
